def _seed_rules() -> None:
    rules = sa.table(
        "doa_rules",
        sa.column("id", sa.UUID()),
        sa.column("doc_type", sa.String()),
        sa.column("name", sa.String()),
        sa.column("priority", sa.Integer()),
        sa.column("condition", sa.dialects.postgresql.JSONB()),
        sa.column("escalation_hours", sa.Integer()),
        sa.column("escalate_to_role", sa.String()),
    )
    steps = sa.table(
        "doa_rule_steps",
        sa.column("rule_id", sa.UUID()),
        sa.column("seq", sa.Integer()),
        sa.column("approver_role", sa.String()),
        sa.column("label", sa.String()),
        sa.column("approver_scope", sa.String()),
    )
    rule_rows, step_rows = [], []
    for r in RULES:
        rid = uuid.uuid4()
        rule_rows.append(
            {
                "id": rid,
                "doc_type": r.doc_type,
                "name": r.name,
                "priority": r.priority,
                "condition": json.loads(json.dumps(r.condition or {})),
                "escalation_hours": r.escalation_hours,
                "escalate_to_role": r.escalate_to_role,
            }
        )
        step_rows += [
            {"rule_id": rid, "seq": st.seq, "approver_role": st.role, "label": st.label, "approver_scope": st.scope}
            for st in r.steps
        ]
    op.bulk_insert(rules, rule_rows)
    op.bulk_insert(steps, step_rows)



